# What Gradescope loads for each test group: the student's definitions, and the notebook globals it supplies.
GRADESCOPE_LOADS = [
    (("build_person_to_kv_map",), {"SELECTED_RELATIONS", "tqdm"}),
    (("build_qkmem_dataset",), {"SELECTED_RELATIONS", "tqdm"}),
    (("QKMemNet",), {"torch", "nn", "F", "Any"}),
    (("evaluate", "Vocab"), {"torch", "np", "Counter", "List", "unidecode", "DEVICE", "nlp", "VOCAB"}),
    (("train_qkmem_model", "Vocab"), {"torch", "nn", "optim", "F", "np", "random", "deepcopy", "tqdm", "List",
                                      "unidecode", "DEVICE", "nlp", "VOCAB", "evaluate"}),
]


def notebook_definitions(cells):
    """{name: its top-level statement, or None for a variable Gradescope does not load}. A later
    definition wins. Gradescope loads imports, functions, classes, literals and aliases."""
    definitions = {}
    for cell in cells:
        source = "".join("\n" if line.lstrip().startswith(("!", "%")) else line
                         for line in cell.splitlines(keepends=True))
        try:
            tree = ast.parse(source)
        except SyntaxError:
            continue
        for node in tree.body:
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                definitions[node.name] = node
            elif isinstance(node, (ast.Import, ast.ImportFrom)):
                definitions.update({alias.asname or alias.name.split(".")[0]: node for alias in node.names})
            elif isinstance(node, (ast.Assign, ast.AnnAssign)) and node.value is not None:
                try:
                    ast.literal_eval(node.value)
                    loaded = node
                except (ValueError, TypeError):
                    loaded = node if isinstance(node.value, ast.Name) else None
                targets = node.targets if isinstance(node, ast.Assign) else [node.target]
                definitions.update({target.id: loaded for target in targets if isinstance(target, ast.Name)})
    return definitions


def global_names(node):
    """The global names a top-level statement uses, including inside nested functions."""
    def collect(scope):
        names = {symbol.get_name() for symbol in scope.get_symbols() if symbol.is_referenced()
                 and (scope.get_type() == "module" or symbol.is_global())}
        for child in scope.get_children():
            names |= collect(child)
        return names

    return collect(symtable.symtable(ast.unparse(node), "<notebook>", "exec"))


def missing_on_gradescope(cells):
    """{student definition: notebook variables it uses that Gradescope will not have}."""
    definitions = notebook_definitions(cells)
    found = {}
    for roots, supplied in GRADESCOPE_LOADS:
        for root in roots:
            seen, todo = set(), [root] if root in definitions else []
            while todo:
                name = todo.pop()
                if name in seen or name in supplied:
                    continue
                seen.add(name)
                if definitions.get(name) is not None:
                    todo += global_names(definitions[name])
                elif name in definitions or not hasattr(builtins, name):
                    found.setdefault(root, set()).add(name)
    return found


def run_all(build_person_to_kv_map, build_qkmem_dataset, QKMemNet,
            evaluate, train_qkmem_model, Vocab):
    """Print each check's score and return the total, out of 20 points."""
    student = {
        "build_person_to_kv_map": build_person_to_kv_map,
        "build_qkmem_dataset": build_qkmem_dataset,
        "QKMemNet": QKMemNet,
        "evaluate": evaluate,
        "train_qkmem_model": train_qkmem_model,
        "Vocab": Vocab,
    }

    # Notebook functions and helpers usually share one globals dictionary.
    namespaces = {}
    for value in student.values():
        members = vars(value).values() if isinstance(value, type) else [value]
        for member in members:
            member = getattr(member, "__func__", member)
            namespace = getattr(member, "__globals__", None)
            if namespace is not None:
                namespaces[id(namespace)] = namespace

    test_globals = {
        "torch": torch, "nn": nn, "optim": optim, "F": F, "np": np,
        "random": random, "deepcopy": deepcopy, "tqdm": tqdm,
        "Counter": Counter, "List": List, "Any": Any, "unidecode": unidecode,
        "DEVICE": torch.device("cpu"), "nlp": spacy.blank("en"),
    }
    # In is the notebook's cell history. A plain script has none, so it gets no warning.
    missing = missing_on_gradescope(next((n["In"] for n in namespaces.values() if "In" in n), []))
    if missing:
        print("These notebook variables won't exist on Gradescope, which runs only imports, functions, "
              "classes, and constants. Use the function's arguments instead:")
        for name, variables in missing.items():
            print(f"  {name} uses {', '.join(sorted(variables))}")
        print()

    total = 0
    print("Part B self-tests")
    for number, test_class, method_name in CHECKS:
        test = test_class(method_name)
        test.student = student
        test.namespaces = list(namespaces.values())
        method = getattr(test, method_name)
        score = 0
        problem = None

        # Restore notebook globals and random states, including after a failure.
        python_state = random.getstate()
        numpy_state = np.random.get_state()
        torch_state = torch.get_rng_state()
        try:
            with ExitStack() as stack:
                for namespace in test.namespaces:
                    stack.enter_context(patch.dict(
                        namespace,
                        {**test_globals, "SELECTED_RELATIONS": SELECTED_RELATIONS.copy()},
                    ))
                # Keep training logs out of the score summary.
                output = io.StringIO()
                stack.enter_context(redirect_stdout(output))
                stack.enter_context(redirect_stderr(output))
                test.setUp()
                method()
                score = POINTS[number]
        except Exception as error:
            problem = f"{type(error).__name__}: {error}"
        finally:
            random.setstate(python_state)
            np.random.set_state(numpy_state)
            torch.set_rng_state(torch_state)

        print(f"{number} {method.__doc__}: {score:g}/{POINTS[number]:g}")
        if problem:
            print("  " + problem.replace("\n", "\n  "))
        total += score

    print(f"Total: {total:g}/{sum(POINTS.values()):g}")
    return total
